-- PT102-S3-Q16. Batch 06.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch06$PT102-S3-Q16$batch06$ AND q.stimulus=$batch06$Motorcoach driver: Professional drivers spend much more time driving, on average, than do other people and hence are more competent drivers than are other, less experienced drivers. Therefore, the speed limit on major highways should not be reduced, because that action would have the undesirable effect of forcing some people who are now both law-abiding and competent drivers to break the law.

Police officer: All drivers can drive within the legal speed limit if they wish, so it is not true to say that reducing the speed limit would be the cause of such illegal behavior.$batch06$ AND q.prompt=$batch06$The point at issue between the motorcoach driver and the police officer is whether$batch06$ AND q.correct_choice=$batch06$C$batch06$) THEN RAISE EXCEPTION 'Question changed: PT102-S3-Q16'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch06$PT102-S3-Q16$batch06$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT102-S3-Q16'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch06$PT102-S3-Q16$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch06$Motorcoach driver's Position$batch06$, $batch06$Lowering the speed limit would force some competent, law-abiding drivers to break the law, so it should not be lowered.$batch06$), (1, $batch06$Police officer's Position$batch06$, $batch06$Every driver can stay under the limit if they want to, so a lower limit would not *cause* anyone to break the law.$batch06$), (2, $batch06$Evaluate$batch06$, $batch06$The officer answers only one of the driver's claims: that a lower limit would *cause* lawbreaking. The officer says nothing about whether professional drivers are more competent, or whether lowering the limit is a good idea. The clash is on cause.$batch06$), (3, $batch06$Goal$batch06$, $batch06$Whether lowering the speed limit would cause some drivers to break the law.$batch06$)) v(position,label,body) WHERE q.qid=$batch06$PT102-S3-Q16$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch06$A$batch06$, $batch06$This is the most popular wrong answer. The driver clearly thinks lowering the limit is undesirable. But the officer never says whether it is a good idea. They only dispute the "cause" claim, so we cannot support the officer's side here.$batch06$), ($batch06$B$batch06$, $batch06$The officer says drivers *can* stay within the limit, not that they *will*. "Can" and "will" are different claims.$batch06$), ($batch06$C$batch06$, $batch06$The driver says a lower limit would force lawbreaking. The officer says it would not be the cause. That is the disagreement.$batch06$), ($batch06$D$batch06$, $batch06$The driver says professionals are more competent. The officer does not address competence.$batch06$), ($batch06$E$batch06$, $batch06$Neither speaker talks about what all drivers *wish*.$batch06$)) v(letter,body) WHERE q.qid=$batch06$PT102-S3-Q16$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
